/**
 * HTML scanner with exact source ranges.
 *
 * The editor must rewrite the user's files without reformatting them, so
 * every node carries byte offsets for its open tag, attributes, inner
 * content and close tag. Edits are then pure range replacements.
 *
 * Deliberately a small, tolerant tokenizer rather than a full parse5 tree:
 * we need attribute-level offsets, which DOM parsers discard, and the
 * project's pages are generated by `hf new page` (well-formed).
 *
 * Anything the scanner cannot model faithfully is reported in `problems`
 * and the editor refuses to edit that file.
 */

const VOID = new Set([
  'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input',
  'link', 'meta', 'param', 'source', 'track', 'wbr',
]);

const RAW_TEXT = new Set(['script', 'style', 'textarea', 'title']);

const NAME = /[A-Za-z][^\s/>]*/y;

function skipWhitespace(source, pos, end) {
  while (pos < end && /\s/.test(source[pos])) pos += 1;
  return pos;
}

function readName(source, pos, end) {
  NAME.lastIndex = pos;
  const match = NAME.exec(source);
  if (!match || NAME.lastIndex > end) return null;
  return { name: match[0].toLowerCase(), end: NAME.lastIndex };
}

/** Parses attributes in `source[from, to)` (inside an open tag, after the name). */
function parseAttributes(source, from, to) {
  const attrs = [];
  let pos = from;
  while (pos < to) {
    pos = skipWhitespace(source, pos, to);
    if (pos >= to) break;
    if (source[pos] === '/') {
      pos += 1;
      continue;
    }
    const nameStart = pos;
    while (pos < to && !/[\s=/>]/.test(source[pos])) pos += 1;
    const name = source.slice(nameStart, pos);
    if (!name) {
      pos += 1;
      continue;
    }
    const afterName = pos;
    pos = skipWhitespace(source, pos, to);
    if (source[pos] !== '=') {
      attrs.push({
        name: name.toLowerCase(),
        value: '',
        quote: '',
        boolean: true,
        nameStart,
        nameEnd: afterName,
        start: nameStart,
        end: afterName,
        valueStart: nameStart,
        valueEnd: afterName,
      });
      continue;
    }
    pos += 1;
    pos = skipWhitespace(source, pos, to);
    const quote = source[pos] === '"' || source[pos] === "'" ? source[pos] : '';
    let valueStart;
    let valueEnd;
    if (quote) {
      valueStart = pos + 1;
      pos = valueStart;
      while (pos < to && source[pos] !== quote) pos += 1;
      valueEnd = pos;
      pos += 1;
    } else {
      valueStart = pos;
      while (pos < to && !/[\s>]/.test(source[pos])) pos += 1;
      valueEnd = pos;
    }
    attrs.push({
      name: name.toLowerCase(),
      value: source.slice(valueStart, valueEnd),
      quote: quote || '',
      boolean: false,
      nameStart,
      nameEnd: afterName,
      start: nameStart,
      end: pos,
      valueStart,
      valueEnd,
    });
  }
  return attrs;
}

function indexOfClose(source, tag, from) {
  const lower = source.toLowerCase();
  let pos = lower.indexOf(`</${tag}`, from);
  while (pos !== -1) {
    const next = lower[pos + 2 + tag.length];
    if (next === undefined || next === '>' || next === '/' || /\s/.test(next)) return pos;
    pos = lower.indexOf(`</${tag}`, pos + 1);
  }
  return -1;
}

/**
 * @param {string} source
 * @returns {{root: object, nodes: object[], problems: {message: string, offset: number}[]}}
 */
export function scanHtml(source, { baseOffset = 0, file = '' } = {}) {
  const nodes = [];
  const problems = [];
  const root = {
    id: '0',
    tag: '#document',
    depth: -1,
    parent: null,
    children: [],
    open: { start: baseOffset, end: baseOffset },
    inner: { start: baseOffset, end: baseOffset + source.length },
    close: null,
    attrs: [],
    file,
  };
  const stack = [root];
  let i = 0;

  while (i < source.length) {
    const lt = source.indexOf('<', i);
    if (lt === -1) break;
    i = lt;

    if (source.startsWith('<!--', i)) {
      const end = source.indexOf('-->', i + 4);
      if (end === -1) {
        problems.push({ message: 'unterminated comment', offset: baseOffset + i });
        break;
      }
      i = end + 3;
      continue;
    }
    if (source.startsWith('<![CDATA[', i)) {
      const end = source.indexOf(']]>', i + 9);
      i = end === -1 ? source.length : end + 3;
      continue;
    }
    if (source.startsWith('<!', i) || source.startsWith('<?', i)) {
      const end = source.indexOf('>', i);
      if (end === -1) {
        problems.push({ message: 'unterminated declaration', offset: baseOffset + i });
        break;
      }
      i = end + 1;
      continue;
    }

    if (source[i + 1] === '/') {
      const parsed = readName(source, i + 2, source.length);
      const gt = parsed ? source.indexOf('>', parsed.end) : -1;
      if (!parsed || gt === -1) {
        problems.push({ message: 'malformed close tag', offset: baseOffset + i });
        i += 2;
        continue;
      }
      const tag = parsed.name;
      let found = -1;
      for (let s = stack.length - 1; s > 0; s -= 1) {
        if (stack[s].tag === tag) {
          found = s;
          break;
        }
      }
      if (found === -1) {
        problems.push({ message: `stray </${tag}>`, offset: baseOffset + i });
      } else {
        for (let s = stack.length - 1; s > found; s -= 1) {
          const orphan = stack.pop();
          orphan.inner.end = i;
          orphan.close = null;
          problems.push({ message: `<${orphan.tag}> implicitly closed by </${tag}>`, offset: baseOffset + i });
        }
        const node = stack.pop();
        node.inner.end = i;
        node.close = { start: baseOffset + i, end: baseOffset + gt + 1 };
      }
      i = gt + 1;
      continue;
    }

    const parsed = readName(source, i + 1, source.length);
    if (!parsed) {
      i += 1;
      continue;
    }
    // `<` followed by a name but not a tag (e.g. "a < b"): require a terminator.
    const gt = source.indexOf('>', parsed.end);
    if (gt === -1) {
      problems.push({ message: `unterminated <${parsed.name}>`, offset: baseOffset + i });
      break;
    }
    const inner = source.slice(parsed.end, gt);
    if (/</.test(inner)) {
      problems.push({ message: `unexpected "<" inside <${parsed.name}>`, offset: baseOffset + i });
      i += 1;
      continue;
    }

    const tag = parsed.name;
    const selfClosing = /\/\s*$/.test(inner);
    // The trailing slash index is relative to `inner`; the attribute range
    // must end at its absolute offset, or every `<x a="b" />` loses `a`.
    const attrsEnd = selfClosing ? parsed.end + inner.lastIndexOf('/') : gt;
    const parent = stack[stack.length - 1];
    const node = {
      id: '',
      tag,
      depth: parent.depth + 1,
      parent,
      children: [],
      open: { start: baseOffset + i, end: baseOffset + gt + 1 },
      inner: { start: baseOffset + gt + 1, end: baseOffset + gt + 1 },
      close: null,
      attrs: parseAttributes(source, parsed.end, attrsEnd),
      selfClosing,
      // `void` means "cannot have children" — true for `<br>` and friends, and
      // false for `<body />`, which is just an empty element with an omitted
      // end tag. Conflating the two made a bare page impossible to frame.
      void: VOID.has(tag),
      file,
    };
    parent.children.push(node);
    nodes.push(node);

    // `<br>` can never have children; `<body />` explicitly has none. Both
    // skip content parsing, but only the first is `void` for editing purposes.
    if (node.void || node.selfClosing) {
      i = gt + 1;
      continue;
    }

    if (RAW_TEXT.has(tag)) {
      const closeAt = indexOfClose(source, tag, gt + 1);
      if (closeAt === -1) {
        node.inner.end = source.length;
        problems.push({ message: `<${tag}> is never closed`, offset: baseOffset + i });
        i = source.length;
      } else {
        node.inner.end = baseOffset + closeAt;
        const closeGt = source.indexOf('>', closeAt);
        node.close = { start: baseOffset + closeAt, end: baseOffset + closeGt + 1 };
        i = closeGt + 1;
      }
      continue;
    }

    stack.push(node);
    i = gt + 1;
  }

  for (let s = stack.length - 1; s > 0; s -= 1) {
    const orphan = stack[s];
    orphan.inner.end = baseOffset + source.length;
    problems.push({ message: `<${orphan.tag}> is never closed`, offset: baseOffset + source.length });
  }

  // Assign stable path ids: "0" root, then child indexes.
  const assign = (node, id) => {
    node.id = id;
    node.children.forEach((child, index) => assign(child, `${id}.${index}`));
  };
  assign(root, '0');

  return { root, nodes, problems, source, baseOffset };
}

/** All elements (skips the document node), in document order. */
export function elements(tree) {
  return tree.nodes;
}

export function findNode(tree, id) {
  return tree.nodes.find((node) => node.id === id) || (id === '0' ? tree.root : null);
}

export function attr(node, name) {
  const lower = name.toLowerCase();
  return node.attrs.find((entry) => entry.name === lower) || null;
}

export function textOf(source, node) {
  return source.slice(node.inner.start, node.inner.end);
}

/** Ancestors from the node up to the root. */
export function ancestors(node) {
  const chain = [];
  let current = node.parent;
  while (current) {
    chain.push(current);
    current = current.parent;
  }
  return chain;
}

/** Index path (`0.1.2`) reused by the client tree. */
export function pathOf(node) {
  return node.id;
}

export function describe(node) {
  if (!node) return '?';
  const id = attr(node, 'id');
  const cls = attr(node, 'class');
  return `<${node.tag}${id ? `#${id.value}` : ''}${cls ? `.${cls.value.trim().split(/\s+/).join('.')}` : ''}>`;
}
